[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>CommerceForge Dev Docs</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg-primary: #0d1117;
      --bg-secondary: #161b22;
      --bg-tertiary: #21262d;
      --bg-card: rgba(33, 38, 45, 0.6);
      --border: #30363d;
      --border-subtle: #21262d;
      --text-primary: #e6edf3;
      --text-secondary: #8b949e;
      --text-muted: #6e7681;
      --accent-green: #3fb950;
      --accent-cyan: #58a6ff;
      --accent-orange: #f78166;
      --accent-purple: #a371f7;
      --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
      --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font-sans);
      background: var(--bg-primary);
      color: var(--text-primary);
      line-height: 1.6;
      min-height: 100vh;
    }

    a { color: var(--accent-cyan); text-decoration: none; transition: color 0.15s ease; }
    a:hover { color: #79c0ff; }

    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

    /* Navigation */
    .nav {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(13, 17, 23, 0.85);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border-subtle);
    }

    .nav-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .nav-brand {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 600;
      font-size: 18px;
      color: var(--text-primary);
    }

    .nav-brand svg { color: var(--accent-green); }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 8px;
      list-style: none;
    }

    .nav-links a {
      padding: 8px 12px;
      color: var(--text-secondary);
      font-size: 14px;
      font-weight: 500;
      border-radius: 6px;
      transition: all 0.15s ease;
    }

    .nav-links a:hover { color: var(--text-primary); background: var(--bg-tertiary); }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .search-btn {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: 6px;
      color: var(--text-muted);
      font-size: 14px;
      cursor: pointer;
      transition: all 0.15s ease;
    }

    .search-btn:hover { border-color: var(--accent-cyan); color: var(--text-secondary); }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 8px 16px;
      border-radius: 6px;
      font-size: 14px;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.15s ease;
      border: none;
    }

    .btn-primary {
      background: var(--accent-green);
      color: #0d1117;
    }

    .btn-primary:hover { background: #4ade80; color: #0d1117; }

    .btn-secondary {
      background: transparent;
      border: 1px solid var(--border);
      color: var(--text-secondary);
    }

    .btn-secondary:hover { border-color: var(--accent-cyan); color: var(--text-primary); }

    .mobile-menu-btn {
      display: none;
      background: none;
      border: none;
      color: var(--text-primary);
      cursor: pointer;
      padding: 8px;
    }

    /* Hero */
    .hero {
      padding: 96px 0 80px;
      text-align: center;
      background: linear-gradient(180deg, rgba(63, 185, 80, 0.08) 0%, transparent 50%);
    }

    .hero h1 {
      font-size: clamp(36px, 6vw, 56px);
      font-weight: 700;
      letter-spacing: -0.02em;
      margin-bottom: 20px;
      background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-green) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero p {
      font-size: 18px;
      color: var(--text-secondary);
      max-width: 640px;
      margin: 0 auto 40px;
      line-height: 1.7;
    }

    .hero-ctas {
      display: flex;
      gap: 12px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .hero-ctas .btn {
      padding: 12px 24px;
      font-size: 15px;
    }

    /* Product Cards */
    .product-cards {
      padding: 80px 0;
    }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-header h2 {
      font-size: 32px;
      font-weight: 600;
      margin-bottom: 12px;
    }

    .section-header p {
      color: var(--text-secondary);
      font-size: 16px;
    }

    .cards-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
      gap: 24px;
    }

    .card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 32px;
      backdrop-filter: blur(8px);
      transition: all 0.2s ease;
    }

    .card:hover {
      border-color: var(--accent-green);
      transform: translateY(-2px);
      box-shadow: 0 8px 32px rgba(63, 185, 80, 0.1);
    }

    .card-icon {
      width: 48px;
      height: 48px;
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }

    .card-icon.apps { background: rgba(63, 185, 80, 0.15); color: var(--accent-green); }
    .card-icon.storefronts { background: rgba(88, 166, 255, 0.15); color: var(--accent-cyan); }
    .card-icon.agents { background: rgba(163, 113, 247, 0.15); color: var(--accent-purple); }

    .card h3 {
      font-size: 20px;
      font-weight: 600;
      margin-bottom: 12px;
    }

    .card p {
      color: var(--text-secondary);
      font-size: 15px;
      margin-bottom: 20px;
      line-height: 1.6;
    }

    .card .btn {
      width: 100%;
      justify-content: center;
      padding: 10px 20px;
    }

    /* CLI Setup */
    .cli-section {
      padding: 80px 0;
      background: var(--bg-secondary);
    }

    .cli-section .section-header { margin-bottom: 40px; }

    .cli-intro {
      text-align: center;
      max-width: 640px;
      margin: 0 auto 48px;
    }

    .cli-intro h2 {
      font-size: 32px;
      font-weight: 600;
      margin-bottom: 16px;
    }

    .cli-intro p {
      color: var(--text-secondary);
      font-size: 16px;
      line-height: 1.7;
    }

    .cli-tabs {
      display: flex;
      gap: 4px;
      background: var(--bg-tertiary);
      padding: 4px;
      border-radius: 8px;
      width: fit-content;
      margin: 0 auto 24px;
    }

    .cli-tab {
      padding: 10px 20px;
      background: transparent;
      border: none;
      border-radius: 6px;
      color: var(--text-secondary);
      font-size: 14px;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.15s ease;
      font-family: var(--font-mono);
    }

    .cli-tab:hover { color: var(--text-primary); }

    .cli-tab.active {
      background: var(--accent-green);
      color: #0d1117;
    }

    .cli-code-block {
      background: var(--bg-primary);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 20px 24px;
      font-family: var(--font-mono);
      font-size: 14px;
      max-width: 480px;
      margin: 0 auto 32px;
    }

    .cli-code-block .prompt {
      color: var(--accent-green);
      margin-right: 8px;
    }

    .cli-code-block .cmd {
      color: var(--text-primary);
    }

    .cli-accordions {
      max-width: 640px;
      margin: 0 auto;
    }

    .accordion {
      border: 1px solid var(--border);
      border-radius: 8px;
      margin-bottom: 12px;
      overflow: hidden;
      background: var(--bg-primary);
    }

    .accordion-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 20px;
      background: transparent;
      border: none;
      width: 100%;
      text-align: left;
      cursor: pointer;
      transition: background 0.15s ease;
      font-family: var(--font-sans);
    }

    .accordion-header:hover { background: var(--bg-tertiary); }

    .accordion-title {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 15px;
      font-weight: 500;
      color: var(--text-primary);
    }

    .accordion-title svg {
      color: var(--accent-cyan);
      transition: transform 0.2s ease;
    }

    .accordion.open .accordion-title svg { transform: rotate(90deg); }

    .accordion-icon {
      color: var(--text-muted);
      transition: transform 0.2s ease;
    }

    .accordion.open .accordion-icon { transform: rotate(180deg); }

    .accordion-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.3s ease;
    }

    .accordion.open .accordion-content { max-height: 500px; }

    .accordion-body {
      padding: 0 20px 20px;
    }

    .accordion-body ol {
      padding-left: 20px;
      color: var(--text-secondary);
      font-size: 14px;
      line-height: 1.8;
    }

    .accordion-body code {
      background: var(--bg-tertiary);
      padding: 2px 6px;
      border-radius: 4px;
      font-family: var(--font-mono);
      font-size: 13px;
      color: var(--accent-green);
    }

    /* Launch CTA */
    .launch-section {
      padding: 80px 0;
    }

    .launch-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
      gap: 24px;
    }

    .launch-card {
      background: linear-gradient(135deg, var(--bg-card) 0%, var(--bg-secondary) 100%);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 32px;
    }

    .launch-card h3 {
      font-size: 20px;
      font-weight: 600;
      margin-bottom: 12px;
    }

    .launch-card p {
      color: var(--text-secondary);
      font-size: 15px;
      margin-bottom: 20px;
      line-height: 1.6;
    }

    /* Community */
    .community-section {
      padding: 80px 0;
      background: var(--bg-secondary);
    }

    .community-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 16px;
    }

    .community-card {
      display: flex;
      align-items: center;
      gap: 16px;
      padding: 20px;
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 8px;
      transition: all 0.15s ease;
      cursor: pointer;
    }

    .community-card:hover {
      border-color: var(--accent-cyan);
      background: var(--bg-tertiary);
    }

    .community-card svg {
      color: var(--accent-cyan);
      flex-shrink: 0;
    }

    .community-card span {
      font-size: 15px;
      font-weight: 500;
      color: var(--text-primary);
    }

    /* Footer */
    .footer {
      padding: 48px 0;
      border-top: 1px solid var(--border-subtle);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 32px;
      margin-bottom: 40px;
    }

    .footer-col h4 {
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--text-muted);
      margin-bottom: 16px;
    }

    .footer-col ul {
      list-style: none;
    }

    .footer-col li { margin-bottom: 10px; }

    .footer-col a {
      font-size: 14px;
      color: var(--text-secondary);
    }

    .footer-col a:hover { color: var(--text-primary); }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 24px;
      border-top: 1px solid var(--border-subtle);
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-bottom p {
      font-size: 13px;
      color: var(--text-muted);
    }

    /* Responsive */
    @media (max-width: 768px) {
      .nav-links { display: none; }
      .mobile-menu-btn { display: flex; }
      .hero { padding: 64px 0 48px; }
      .hero h1 { font-size: 32px; }
      .cards-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-bottom { flex-direction: column; text-align: center; }
    }

    @media (max-width: 480px) {
      .hero-ctas { flex-direction: column; }
      .hero-ctas .btn { width: 100%; justify-content: center; }
      .footer-grid { grid-template-columns: 1fr; }
    }
  </style>
</head>
<body>
  <!-- Navigation -->
  <nav class="nav">
    <div class="nav-inner">
      <div class="nav-brand">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/>
        </svg>
        CommerceForge
      </div>
      <ul class="nav-links">
        <li><a href="apps-build.html">Apps</a></li>
        <li><a href="storefronts.html">Storefronts</a></li>
        <li><a href="agents.html">Agents</a></li>
        <li><a href="#">References</a></li>
        <li><a href="support.html">Help</a></li>
      </ul>
      <div class="nav-actions">
        <button class="search-btn">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>
          </svg>
          Search docs
        </button>
        <button class="btn btn-primary">Log in</button>
        <button class="mobile-menu-btn">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="18" x2="21" y2="18"/>
          </svg>
        </button>
      </div>
    </div>
  </nav>

  <!-- Hero -->
  <section class="hero">
    <div class="container">
      <h1>CommerceForge Dev Docs</h1>
      <p>Learn how to build an app, or customize your storefront. Whether you're just getting started, deep in the development process, or ready to distribute and monetize your work, CommerceForge's docs, dev tools and frameworks make building easy and efficient.</p>
      <div class="hero-ctas">
        <a href="apps-build.html" class="btn btn-primary">Build your first app →</a>
        <a href="storefronts.html" class="btn btn-secondary">Build a storefront →</a>
        <a href="agents.html" class="btn btn-secondary">Build agents with UCP →</a>
      </div>
    </div>
  </section>

  <!-- Product Cards -->
  <section class="product-cards">
    <div class="container">
      <div class="section-header">
        <h2>Product Areas</h2>
        <p>Everything you need to build on CommerceForge</p>
      </div>
      <div class="cards-grid">
        <div class="card">
          <div class="card-icon apps">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 9h6v6H9z"/>
            </svg>
          </div>
          <h3>Apps</h3>
          <p>Extend CommerceForge's core functionality with apps that integrate into the admin, online store, checkout and more.</p>
          <a href="apps-build.html" class="btn btn-primary">Build your first app →</a>
        </div>
        <div class="card">
          <div class="card-icon storefronts">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9,22 9,12 15,12 15,22"/>
            </svg>
          </div>
          <h3>Storefronts</h3>
          <p>Help merchants express their unique brand by building a custom theme or Hydrogen storefront.</p>
          <a href="storefronts.html" class="btn btn-secondary">Build a storefront →</a>
        </div>
        <div class="card">
          <div class="card-icon agents">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M12 2a10 10 0 1 0 10 10H12V2z"/><path d="M12 2a10 10 0 0 1 10 10"/><circle cx="12" cy="12" r="3"/>
            </svg>
          </div>
          <h3>Agents</h3>
          <p>Build agentic shopping experiences powered by CommerceForge merchants, from product discovery to checkout.</p>
          <a href="agents.html" class="btn btn-secondary">Build agents with UCP →</a>
        </div>
      </div>
    </div>
  </section>

  <!-- CLI Setup -->
  <section class="cli-section">
    <div class="container">
      <div class="cli-intro">
        <h2>Accelerate development with CommerceForge CLI 3.0</h2>
        <p>Initialize new apps, themes, and headless storefronts in an instant with the latest CommerceForge CLI. A single command installs all the dependencies you need, including the CLI itself, so you can dive straight into development.</p>
      </div>

      <!-- Package Manager Tabs -->
      <div class="cli-tabs">
        <button class="cli-tab active" data-pkg="npm">npm</button>
        <button class="cli-tab" data-pkg="yarn">yarn</button>
        <button class="cli-tab" data-pkg="pnpm">pnpm</button>
      </div>

      <div class="cli-code-block">
        <span class="prompt">$</span>
        <span class="cmd install-cmd">npm i -g @commerceforge/cli@latest</span>
      </div>

      <!-- Accordions -->
      <div class="cli-accordions">
        <div class="accordion" data-type="apps">
          <button class="accordion-header">
            <span class="accordion-title">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <polyline points="9,18 15,12 9,6"/>
              </svg>
              Apps
            </span>
            <svg class="accordion-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <polyline points="6,9 12,15 18,9"/>
            </svg>
          </button>
          <div class="accordion-content">
            <div class="accordion-body">
              <ol>
                <li>Install CommerceForge CLI globally.</li>
                <li>Navigate to the directory where you want to create your app.</li>
                <li>Run <code>commerceforge app init</code> to create a new app. Your app will be added as a new subdirectory.</li>
              </ol>
            </div>
          </div>
        </div>

        <div class="accordion" data-type="themes">
          <button class="accordion-header">
            <span class="accordion-title">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <polyline points="9,18 15,12 9,6"/>
              </svg>
              Themes
            </span>
            <svg class="accordion-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <polyline points="6,9 12,15 18,9"/>
            </svg>
          </button>
          <div class="accordion-content">
            <div class="accordion-body">
              <ol>
                <li>Install CommerceForge CLI globally.</li>
                <li>Navigate to the directory where you want to create your theme.</li>
                <li>Run <code>commerceforge theme init</code> to clone a starter theme. Your theme will be created in a new subdirectory.</li>
              </ol>
            </div>
          </div>
        </div>

        <div class="accordion" data-type="headless">
          <button class="accordion-header">
            <span class="accordion-title">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <polyline points="9,18 15,12 9,6"/>
              </svg>
              Headless storefronts
            </span>
            <svg class="accordion-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <polyline points="6,9 12,15 18,9"/>
            </svg>
          </button>
          <div class="accordion-content">
            <div class="accordion-body">
              <ol>
                <li>Install CommerceForge CLI globally.</li>
                <li>Navigate to the directory where you want to create your Hydrogen storefront.</li>
                <li>Run <code>commerceforge hydrogen init</code> to initialize a Hydrogen storefront in a new subdirectory.</li>
              </ol>
            </div>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- Launch CTA -->
  <section class="launch-section">
    <div class="container">
      <div class="section-header">
        <h2>Ready to Launch?</h2>
        <p>Distribute your work to millions of merchants</p>
      </div>
      <div class="launch-grid">
        <div class="launch-card">
          <h3>App Marketplace</h3>
          <p>When you're ready, submit your app to the CommerceForge App Marketplace so merchants can find and buy your app through search or personalized recommendations.</p>
          <a href="#" class="btn btn-primary">See App Marketplace requirements →</a>
        </div>
        <div class="launch-card">
          <h3>Theme Store</h3>
          <p>Promote and sell your custom theme to merchants building their brands on the CommerceForge Theme Store.</p>
          <a href="#" class="btn btn-primary">See Theme Store requirements →</a>
        </div>
      </div>
    </div>
  </section>

  <!-- Community -->
  <section class="community-section">
    <div class="container">
      <div class="section-header">
        <h2>Community Resources</h2>
        <p>Join the CommerceForge developer community</p>
      </div>
      <div class="community-grid">
        <a href="#" class="community-card">
